@testset "view_domain: cut" begin
    d = create_domain([0.4, 0.6, 1.0], [0.1, 0.2, 0.25])
    @test _VIEW._cut_positions(d, 1) == d.nodes_u
    @test _VIEW._cut_positions(d, 3) == d.nodes_w

    # the plane keeps what lies below the position and hides what lies beyond
    for axis in 1:3
        plane = _VIEW._clip_plane(axis, 0.3)
        below = Point3f(ntuple(i -> i == axis ? 0.2f0 : 0.5f0, 3))
        above = Point3f(ntuple(i -> i == axis ? 0.4f0 : 0.5f0, 3))
        @test !Makie.is_clipped(plane, below)
        @test Makie.is_clipped(plane, above)
    end

    # the outline of the cut: a closed rectangle in the plane, spanning the domain
    r = _VIEW._cut_rectangle((0, 0, 0), (0.4, 0.6, 1.0), 2, 0.3f0)
    @test length(r) == 5 && r[1] == r[end]
    @test all(p -> p[2] ≈ 0.3, r)
    @test extrema(p[1] for p in r) == (0, 0.4f0) && extrema(p[3] for p in r) == (0, 1.0f0)
end

