@testset "view_domain: grid in the cut plane" begin
    d = create_domain([0.4, 0.6, 1.0], [0.1, 0.2, 0.25])
    segs = _VIEW._cut_grid_segments(d, 2, 0.4)                       # cut along y
    @test length(segs) == 2 * (d.Nu + d.Nw)                          # one line per node of x and z
    @test all(p -> p[2] ≈ 0.4f0, segs)                               # all in the cut plane
    # lines at x = const span the full z range, lines at z = const the full x range
    @test Set(round(p[1]; digits = 4) for p in segs[1:2:2d.Nu]) == Set(round.(Float32.(d.nodes_u); digits = 4))
    @test extrema(p[3] for p in segs) == (0f0, 1f0) && extrema(p[1] for p in segs) == (0f0, 0.4f0)
