@testset "view_domain: loop on its grid edges" begin
    d = create_domain([20.0, 30.0, 30.0], [1.0, 0.5, 0.5])          # the grid of sources.jl
    create_circular_loop_source!(d, 8.0, 10.3, 15.2, 14.9, DirX(); current = -3.0 + 2im, name = "coil")
    loop = only(list_objects(d)).object
    segs, mids, dirs = _VIEW._loop_edges(d, loop)
    J = get_source(d, "coil")
    @test length(segs) == 2 * count(!iszero, J)                      # one segment per marked edge
    @test all(i -> segs[2i] - segs[2i-1] == abs.(dirs[i]), eachindex(dirs))   # along the edge
    @test all(p -> p[1] ≈ d.nodes_u[argmin(abs.(d.nodes_u .- 10.3))], segs)  # in the loop's node plane

    # closed: every node is the end of an even number of edges
    ends = Dict{Point3f,Int}()
    foreach(p -> ends[p] = get(ends, p, 0) + 1, segs)
    @test all(iseven, values(ends))

    # the arrows circulate counter-clockwise about +u, independent of the complex
    # amplitude: enclosed area ½ Σ (v dw − w dv) > 0 and close to πR²
    A = sum((m[2] * dv[3] - m[3] * dv[2]) / 2 for (m, dv) in zip(mids, dirs))
    @test A ≈ π * 8.0^2 rtol = 0.03
end

@testset "view_domain: voxel labels" begin
    d = create_domain([1.0, 1.0, 1.0], [0.25, 0.25, 0.25])          # 4 × 4 × 4 cells
    create_brick!(d, 0.0, 0.0, 0.0, 0.5, 0.5, 0.5; σ = 5.0)          # cells 1:2
    create_brick!(d, 0.25, 0.25, 0.25, 0.5, 0.5, 0.5; ε_r = 3.0)     # cells 2:3, overlaps
    create_brick!(d, 0.75, 0.75, 0.75, 0.25, 0.25, 0.25)             # removed below
    create_circular_loop_source!(d, 0.2, 0.25, 0.25, 0.25, DirX())   # no cells
    remove_object!(d, 3)
    lab = _VIEW._owner_labels(d)
    @test size(lab) == (4, 4, 4)
    @test lab[1, 1, 1] == 1 && lab[2, 2, 2] == 2 && lab[3, 3, 3] == 2   # the later object wins
    @test lab[4, 4, 4] == 0                                          # removed: background
    @test Set(lab) == Set([0, 1, 2])                                 # no label for the source
    # the labels follow the material exactly
    @test (lab .== 1) == (d.material[:, :, :, 1] .== 5.0)
    @test (lab .== 2) == (d.material[:, :, :, 2] .== 3.0)
end

@testset "view_domain: voxel surface meshes" begin
    faces(m) = length(m.faces) ÷ 2

    d = create_domain([0.3, 0.2, 0.2], [0.1, 0.1, 0.1])              # 3 × 2 × 2 cells
    lab = zeros(Int, 3, 2, 2)
    lab[1, 1, 1] = 7
    m = _VIEW._voxel_meshes(d, lab)
    @test keys(m) == Set([7]) && faces(m[7]) == 6                    # one cell: six faces
    # each face's normal points away from the cell centre
    centre = Point3f(0.05, 0.05, 0.05)
    @test all(m[7].faces) do f
        a, b, c = m[7].position[f[1]], m[7].position[f[2]], m[7].position[f[3]]
        dot(cross(b - a, c - a), (a + b + c) / 3 - centre) > 0
    end

    lab[2, 1, 1] = 7
    @test faces(_VIEW._voxel_meshes(d, lab)[7]) == 10                # the shared face is gone
    lab[2, 1, 1] = 8
    m = _VIEW._voxel_meshes(d, lab)
    @test faces(m[7]) == 6 && faces(m[8]) == 6                       # another object: both keep it

    # a cut after the first cell along x: the second one counts as empty
    lab .= 7
    @test _VIEW._cut_cells(d, 1, 0.1) == (1, 1)
    @test faces(_VIEW._voxel_meshes(d, lab; keep = _VIEW._cut_cells(d, 1, 0.1))[7]) ==
          2 * (2 * 2) + 2 * (1 * 2) + 2 * (1 * 2)                     # a 1 × 2 × 2 block
    @test isempty(_VIEW._voxel_meshes(d, lab; keep = _VIEW._cut_cells(d, 1, 0.0)))

    # graded grid: the corners are the node coordinates
    g = create_domain([0.1, 0.3], [0.2], [0.05, 0.05])
    m = _VIEW._voxel_meshes(g, fill(1, 2, 1, 2))[1]
    @test Set(p[1] for p in m.position) == Set(Float32[0, 0.1, 0.4])
    @test Set(p[3] for p in m.position) == Set(Float32[0, 0.05, 0.1])
end

